 75	function extractConstantValue(string $constant, string $content) : string
 76	{
 77	    // String value: const NAME = 'value';
 78	    if (preg_match('/const\s+' . preg_quote($constant, '/') . '\s*=\s*\'(.*?)\'\s*;/s', $content, $m))
 79	    {
 80	        return $m[1];
 81	    }
 82	
 83	    // Integer value: const NAME = 123;
 84	    if (preg_match('/const\s+' . preg_quote($constant, '/') . '\s*=\s*(\d+)\s*;/', $content, $m))
 85	    {
 86	        return $m[1];
 87	    }
 88	
 89	    // Null literal: const NAME = null;
 90	    if (preg_match('/const\s+' . preg_quote($constant, '/') . '\s*=\s*null\s*;/i', $content, $m))
 91	    {
 92	        return 'null';
 93	    }
 94	
 95	    return '';
 96	}
