125	     * On Windows (or when stty is unavailable) input is read with echo visible
126	     * and a warning is displayed to the user.
127	     *
128	     * @param string $label   The label to display before the input cursor.
129	     * @param string $default The value to use when the user provides no input.
130	     * @return string The trimmed user input, or $default when input is empty.
131	     */
132	    function promptPassword(string $label, string $default = '') : string
133	    {
134	        $sttyAvailable = (DIRECTORY_SEPARATOR !== '\\')
135	            && (shell_exec('stty 2>/dev/null; echo $?') !== null);
136	
137	        if ($default !== '')
138	        {
139	            echo $label . ' [' . str_repeat('*', min(8, strlen($default))) . ']: ';
140	        }
141	        else
142	        {
143	            echo $label . ': ';
144	        }
145	
146	        if ($sttyAvailable)
147	        {
148	            shell_exec('stty -echo');
149	            $input = fgets(STDIN);
150	            shell_exec('stty echo');
151	            echo PHP_EOL;
152	        }
153	        else
154	        {
