280	 * Handles three target value shapes:
281	 *   - String:  const NAME = 'new_value';
282	 *   - Integer: const NAME = 42;
283	 *   - Null:    const NAME = null;
284	 *
285	 * @param string $content   The raw PHP source to process.
286	 * @param string $constant  The constant name to replace.
287	 * @param string $value     The new value as a string (e.g. 'root', '3306', 'null').
288	 * @param bool   $isInt     When true, the value is written as a bare integer.
289	 * @param bool   $isNull    When true, the value is written as `null`.
290	 * @return string The modified source.
291	 */
292	function replaceConfigConstant(
293	    string $content,
294	    string $constant,
295	    string $value,
296	    bool $isInt  = false,
297	    bool $isNull = false
298	) : string {
299	    if ($isNull)
300	    {
301	        $replacement = 'const ' . $constant . ' = null;';
302	    }
303	    elseif ($isInt)
304	    {
305	        $replacement = 'const ' . $constant . ' = ' . $value . ';';
306	    }
307	    else
308	    {
309	        $replacement = 'const ' . $constant . " = '" . addslashes($value) . "';";
310	    }
311	
312	    // Replace any existing `const NAME = ...;` declaration on a single line.
313	    $pattern = '/^const\s+' . preg_quote($constant, '/') . '\s*=\s*[^;]+;/m';
314	
315	    return (string)preg_replace($pattern, $replacement, $content, 1);
