374	 * Steps:
375	 * 1. Try to `USE <dbName>` — if it succeeds the database already exists.
376	 * 2. On failure, `CREATE DATABASE \`<dbName>\`` and select it.
377	 * 3. Read the schema file via `file_get_contents()`.
378	 * 4. Execute the SQL via PDO `exec()`.
379	 *
380	 * Aborts with a non-zero exit code if `CREATE DATABASE` fails (e.g. the
381	 * DB user lacks the required privilege).
382	 *
383	 * @param PDO    $pdo        An open PDO connection (no database selected).
384	 * @param string $dbName     The target database name.
385	 * @param string $schemaFile Absolute path to the SQL schema file.
386	 * @return void
387	 */
388	function ensureDatabase(PDO $pdo, string $dbName, string $schemaFile) : void
389	{
390	    // --- Check if the database already exists ---
391	    $dbExists = false;
392	
393	    try
394	    {
395	        $pdo->exec('USE `' . $dbName . '`');
396	        $dbExists = true;
397	    }
398	    catch (\PDOException $e)
399	    {
400	        // Database does not exist — proceed to create it.
401	    }
402	
403	    if (!$dbExists)
404	    {
405	        writeln('  Creating database `' . $dbName . '`…');
406	
407	        try
408	        {
409	            $pdo->exec('CREATE DATABASE `' . $dbName . '` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');
410	            $pdo->exec('USE `' . $dbName . '`');
411	            writeln('  ' . color('Database created.', 'green'));
412	        }
413	        catch (\PDOException $e)
414	        {
415	            writeln(color('ERROR: Could not create database `' . $dbName . '`.', 'red'));
